{"summary":"Fix restoreRuntime to set phase to 'restoring' initially, then update to 'running' only after all thread IDs are created, ensuring the running state is not exposed prematurely.","files":[{"path":"apps/game-runtime/src/runtime/restore.ts","content":"import type { RuntimeState } from "./types";
import { ThreadBootstrapper } from "./bootstrap";

export type Snapshot = {
  agentIds: string[];
  threadIds: Record<string, string>;
};

export function restoreRuntime(
  snapshot: Snapshot,
  state: RuntimeState,
  bootstrapper: ThreadBootstrapper,
): RuntimeState {
  state.phase = "restoring";
  state.threadIds = {};
  for (const agentId of snapshot.agentIds) {
    state.threadIds[agentId] = bootstrapper.ensureThread(agentId);
  }
  state.phase = "running";
  return state;
}"}]
